function createLatest(load, publish) {
  let revision = 0;
  let disposed = false;
  return {
    async run(query) {
      if (disposed) return;
      const mine = ++revision;
      const value = await load(query);
      if (!disposed && mine === revision) publish(value);
    },
    dispose() { disposed = true; revision++; }
  };
}

